insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Professional Services","heading":"SEO for Professional Services Firms","body":"Professional services buyers research quietly and at length, then contact one or two firms. Most of the decision happens before anyone picks up a phone.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"growth","label":"How clients search","title":"Quietly, Over Weeks","items":["A practice area and a place","A situation in plain words","Several visits, no contact","One or two firms called"]},{"kind":"coverage","label":"What it rests on","title":"Specificity","items":["Service pages","Named people","Clear scope"]}]}'::jsonb, 0 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"numbered","columns":3,"eyebrow":"Who This Is For","heading":"Firms This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Law Firms & Legal Services","icon":"shield-check","body":"Among the most competitive search categories that exists, with a lead value high enough to justify the fight."},{"title":"Accounting & Wealth Management","icon":"bar-chart","body":"Strongly seasonal for some services and steady for others, with a long client relationship at the end of it."},{"title":"Commercial Insurance & Staffing","icon":"briefcase","body":"Sold business to business on specificity and coverage, where a vague services page loses to a precise one."}]}'::jsonb, 1 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Professional Services","body":"Buyers here are cautious and largely invisible. They read, they compare, they check credentials, and they often visit a firm''s site several times over weeks without ever filling in a form. The consequence is that traffic and enquiries move on different timelines, and a report that only shows enquiries misses most of what changed.\n\nThe searches themselves are specific. People look for a practice area plus a place, or a situation described in plain language, and generic pages built around the firm rather than the problem do badly against them. Lead value is high, which changes the arithmetic: a small number of the right visitors is worth more than a large number of the wrong ones, and that is what the tracked keyword set should reflect.","groups":[{"title":"A long, quiet consideration","icon":"clipboard-check","body":"Several visits before contact is normal, so early traffic movement matters before enquiries do."},{"title":"Practice area plus place","icon":"search","body":"Specific pages for specific services beat one broad page that tries to hold all of them."},{"title":"Credibility is a ranking factor in practice","icon":"shield-check","body":"Named people, real detail and clear scope outperform anonymous copy for both readers and search engines."}]}'::jsonb, 2 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Traditional SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nProfessional Services buyers are not searching inside a drive-time radius. The work is specification, capability and procurement language across a region or a country, so a local campaign would optimise for a map pack that the people making these decisions never open.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a firm the answers arrive more slowly than most, because the consideration does.","did":"The work completed that month, named task by task: practice-area pages, the location pairings that go with them, and the material doing the work of credibility before anyone picks up a phone.","why":"Why that work came first, which is usually a practice area with no page behind it, or one competing against firms that have published far more.","changed":"Which practice-area and location searches moved, and what enquiry volume did. Reported honestly, including the months where little moved, which is ordinary in a consideration cycle measured in weeks.","next":"Next month''s priorities in order, with the reasoning behind the order rather than just the list.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Professional Services Questions","items":[{"question":"Why do enquiries lag behind traffic in this sector?","answer":"Because the decision takes weeks and involves several visits. That is normal here, and it is one of the reasons the recap reports what changed in visibility as well as what came through the form."},{"question":"Does a firm need a page per service?","answer":"Generally yes. Clients search for a specific practice area, and a single page trying to cover six of them tends to rank for none of them well."},{"question":"Are results in a competitive practice area realistic?","answer":"In the most contested categories, progress usually starts on more specific searches rather than the broadest term. That is a slower route but a real one, and the reporting is explicit about which stage the work is at."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in professional services?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Energy & Petrochemical","heading":"SEO for Energy and Petrochemical Suppliers","body":"Buyers in this sector search by specification, not by adjective. The work is making a business findable in the exact technical language its customers already use.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"report","label":"How buyers search","title":"By Specification","items":["Standards and materials","Part numbers","Compliance requirements","Never adjectives"]},{"kind":"coverage","label":"Who is searching","title":"Three People, One Purchase","items":["Engineer","Procurement","Approver"]}]}'::jsonb, 0 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"split","columns":3,"eyebrow":"Who This Is For","heading":"Suppliers and Service Firms","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Oil & Gas Field Services & Logistics","icon":"hard-hat","body":"Contracted on capability and compliance, and often searched for during a turnaround or an outage."},{"title":"Petrochemical Plant Services & Contracting","icon":"factory","body":"Qualified long before any conversation, on certifications, safety record and plant experience."},{"title":"Industrial Equipment & Supplies","icon":"layers","body":"Found by part number, specification and standard far more often than by company name."}]}'::jsonb, 1 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Energy","body":"The searches are technical and unglamorous. A procurement manager or an engineer types a specification, a standard, a material or a part number, and the pages that win are the ones that carry those terms in a form a search engine can read. Marketing language actively hurts here, because nobody is searching for a phrase like world-class solutions.\n\nThe cycle is long, often months, and rarely involves one person. An engineer shortlists, procurement checks compliance, and a manager approves, and each of those people arrives through a different search. Competition is regional and national rather than local, which is what puts most of this sector in the Traditional lane, though a small field-service business working one area is a genuine Local engagement.","groups":[{"title":"Specifications, not adjectives","icon":"code","body":"Standards, materials and part numbers are the search terms. Pages have to contain them plainly."},{"title":"Several searchers, one purchase","icon":"users","body":"Technical, compliance and commercial questions each need their own page rather than one overview."},{"title":"Months, not minutes","icon":"calendar","body":"A long cycle means early visibility work shows up in enquiries much later than it shows up in traffic."}]}'::jsonb, 2 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Traditional SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nEnergy & Petrochemical buyers are not searching inside a drive-time radius. The work is specification, capability and procurement language across a region or a country, so a local campaign would optimise for a map pack that the people making these decisions never open.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a technical buyer the answers are about specification coverage rather than keyword counts.","did":"The work completed that month, named task by task: capability and specification pages, the technical detail that makes them findable, and the fixes that let a procurement search reach them at all.","why":"Why that work came first, which is usually a capability the business sells and cannot be found for, or a page written in adjectives where the search was written in specifications.","changed":"Which specification and capability searches moved, and what the enquiries that did arrive were actually looking for. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, on a cycle measured in months rather than weeks, because the buying is.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Energy & Petrochemical Questions","items":[{"question":"Does SEO work when there are only a handful of real buyers?","answer":"It can, because the value of one contract is high enough that a small number of the right visitors justifies the work. It also changes what gets tracked: a narrow, technical keyword set matters far more than total traffic."},{"question":"How is technical content produced without in-house expertise?","answer":"By working from your specifications, datasheets and existing documentation rather than inventing them. Nothing technical is published without your review, because a wrong specification on a page costs more than a missing one."},{"question":"Is this Local or Traditional SEO?","answer":"Usually Traditional, because buyers are spread across markets. A field-service business working one area is a Local engagement, and location count never decides it. Reach does."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in energy & petrochemical?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Maritime & Logistics","heading":"SEO for Maritime and Logistics Operators","body":"Logistics buyers search by route, service and capability, often under time pressure. Being findable in that language is most of the job.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"coverage","label":"How buyers search","title":"By Route and Capability","items":["A route and a mode","A port and a service","A vessel and a repair","Often under time pressure"]},{"kind":"coverage","label":"What it rests on","title":"Coverage and Compliance","items":["Ports served","Certifications","Response"]}]}'::jsonb, 0 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"compact","columns":3,"eyebrow":"Who This Is For","heading":"Operators This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Port Services & Stevedoring","icon":"ship","body":"Searched by service and by port, with capability and certification usually deciding the shortlist."},{"title":"Freight Transport & Warehousing","icon":"network","body":"Route, mode and capacity drive the search, and comparison against several operators is standard."},{"title":"Marine Repair & Industrial Supplies","icon":"wrench","body":"Often urgent, because a vessel out of service is costing money every day it waits."}]}'::jsonb, 1 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Logistics","body":"Logistics search sits between the urgency of a trade and the caution of a procurement purchase. A freight buyer looking for a route and a mode will compare several operators before making contact, but a vessel needing repair is an emergency with a daily cost attached, and those two searches want completely different pages.\n\nThe vocabulary is precise. Routes, ports, vessel types, cargo classes and certifications are the terms people use, and a site organised around company departments rather than around those terms is hard to find no matter how good the business is. Reach varies enormously: a single-yard repair business competes locally, while a freight operator moving cargo across the region competes with operators in other cities for the same contract.","groups":[{"title":"Route, mode, capability","icon":"network","body":"Pages organised by what customers ship and where, rather than by internal department."},{"title":"Downtime makes some searches urgent","icon":"warning","body":"Repair and emergency service searches behave like a trade call, and need to be treated that way."},{"title":"Certifications are search terms","icon":"shield-check","body":"Compliance and accreditation are often the filter, so they belong on the page rather than in a PDF."}]}'::jsonb, 2 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Traditional SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nMaritime & Logistics buyers are not searching inside a drive-time radius. The work is specification, capability and procurement language across a region or a country, so a local campaign would optimise for a map pack that the people making these decisions never open.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a logistics business the answers are organised by route, mode and capability, because that is how the searches are.","did":"The work completed that month, named task by task: route and capability pages, the certification and coverage detail that gets searched for by name, and the technical work behind both.","why":"Why that work came first, which is usually a lane or a capability with no page behind it, or a certification buyers search for that the site never actually states.","changed":"What moved across route, mode and capability searches, and on the urgent ones that only appear when something is down. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, so nothing in the following recap arrives as a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Maritime Questions","items":[{"question":"Do customers really find logistics providers through search?","answer":"For new suppliers and for urgent requirements, frequently. Long-standing contracts come through relationships, but the shortlist for a new route or an unplanned repair is very often built from a search."},{"question":"Should pages be built around routes or around services?","answer":"Both, usually, because they are searched differently. A service page explains capability; a route or port page catches the searches that name a specific place."},{"question":"How is an urgent repair enquiry handled differently?","answer":"Those searches need a fast, obvious path to a phone number and clear coverage information, which is closer to how a trades page works than to how a procurement page works."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in maritime & logistics?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Commercial Construction & Infrastructure","heading":"SEO for Commercial Construction Firms","body":"Commercial construction is won on capability, references and bid lists, but the shortlist is increasingly built by searching. Being on it starts with being findable.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"growth","label":"How buyers search","title":"To Qualify, Not to Enquire","items":["Project type and sector","Scale and scope","Certifications held","Before any invitation"]},{"kind":"coverage","label":"What it rests on","title":"Evidence in Text","items":["Project pages","Capability","Standards met"]}]}'::jsonb, 0 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"numbered","columns":3,"eyebrow":"Who This Is For","heading":"Contractors and Suppliers","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Commercial & Industrial Subcontractors","icon":"hard-hat","body":"Shortlisted on trade, project type and sector experience long before any bid conversation happens."},{"title":"Civil & Roadway Contracting","icon":"building","body":"Public and private procurement with long cycles and a heavy emphasis on qualification."},{"title":"Earthmoving, Crane & Site Services","icon":"layers","body":"Hired on equipment, capacity and availability, frequently at short notice on an active site."}]}'::jsonb, 1 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Construction","body":"The searches that matter here rarely look like lead generation. An architect looking for a product that meets a standard, a developer checking whether a contractor has done a project of a given type before, a procurement team qualifying a supplier: all of them are searching, and none of them will fill in a contact form on the first visit.\n\nThat makes the project and capability pages the working part of a construction site. Sector, project type, scale and qualification are the terms people search, and a portfolio organised as a photo gallery answers none of them. The cycle is measured in months, competition runs regional to national, and the value of a single project means a small volume of exactly the right visitors is the goal rather than traffic.","groups":[{"title":"Qualification, not enquiry","icon":"clipboard-check","body":"Most visitors are checking whether you qualify. The site has to answer that without a conversation."},{"title":"Project type is the search term","icon":"search","body":"Sector and project pages do the ranking. A gallery of photographs does not."},{"title":"Specified before it is bought","icon":"file-text","body":"For suppliers, the decision often happens with the specifier rather than with the buyer."}]}'::jsonb, 2 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a commercial construction & infrastructure business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a contractor the answers are about being qualified, which happens long before anybody calls.","did":"The work completed that month, named task by task: project-type pages, the evidence in text that a qualifying reader is looking for, and the technical work sitting behind both.","why":"Why that work came first, which is usually a project type the business bids on with nothing published about it, or a page that ranks and then fails to qualify the reader who lands on it.","changed":"Which project-type searches moved, and what the enquiries that arrived were bidding on. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, aligned to the project types actually being bid rather than to a content calendar.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Construction Questions","items":[{"question":"Does SEO matter when work comes through bid lists?","answer":"Yes, because getting onto the list increasingly involves being found and checked first. Firms are researched before they are invited, and a thin website removes you from consideration quietly."},{"question":"What should a project portfolio actually contain?","answer":"Project type, sector, scale and scope written as text, not only photographs. That is what people search for, and images alone cannot be read as an answer to it."},{"question":"How long is the payback in this sector?","answer":"Longer than in consumer categories, because the cycle itself is long. The recap tracks visibility and qualification-stage movement in the meantime rather than pretending an enquiry count tells the whole story."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in commercial construction & infrastructure?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/commercial-construction-infrastructure';
